Everything linear-plus-curvature plateaus near 0.71. Testing the actual 3-layer design: layer 1 = silu(+-a*x) for 24 non-duplicate inputs (48 units), layer 2 = silu of one-vs-one class discriminants, readout = LDA on layer-2 activations.
```python
X=np.load("train_x.npy");y=np.load("train_y.npy")
sil=lambda z:z/(1+np.exp(-z))
keep=[j for j in range(27) if j not in (1,3,12)]
def lda(Xa,ya,lam,pri=True):
    M=np.stack([Xa[ya==c].mean(0) for c in range(7)])
    R=Xa-M[ya];S=R.T@R/len(ya);S+=lam*np.trace(S)/S.shape[0]*np.eye(S.shape[0])
    W=np.linalg.solve(S,M.T).T;p=np.log(np.bincount(ya,minlength=7)/len(ya))
    b=-0.5*(W*M).sum(1)+p;return W,b
def l1f(X,a):return np.hstack([sil(a*X[:,keep]),sil(-a*X[:,keep])])
def pairdirs(F,yy,lam):
    D=[];B=[]
    for i in range(7):
        for j in range(i+1,7):
            m=(yy==i)|(yy==j);W,b=lda(F[m],yy[m],lam);w=W[i]-W[j];bb=b[i]-b[j]
            sd=(F[m]@w).std();D.append(w/sd);B.append(bb/sd)
