X=np.load("train_x.npy");y=np.load("train_y.npy")
sil=lambda z:z/(1+np.exp(-z))
keep=[j for j in range(27) if j not in (1,3,12)]
def lda(Xa,ya,lam):
    M=np.stack([Xa[ya==c].mean(0) if (ya==c).any() else np.zeros(Xa.shape[1]) for c in range(7)])
    R=Xa-M[ya];S=R.T@R/len(ya);S+=lam*np.trace(S)/S.shape[0]*np.eye(S.shape[0])
    W=np.linalg.solve(S,M.T).T;p=np.log(np.maximum(np.bincount(ya,minlength=7),1)/len(ya))
    b=-0.5*(W*M).sum(1)+p;return W,b
def build(Xt,yt,a,g,lp,lf,extra):
    W1=np.zeros((48,27))
    for k,j in enumerate(keep):W1[k,j]=a;W1[24+k,j]=-a
    F=sil(Xt@W1.T);D=[];B=[]
    for i in range(7):
        for j in range(i+1,7):
            m=(yt==i)|(yt==j);W,b=lda(F[m],yt[m],lp);w=W[i]-W[j];bb=b[i]-b[j];sd=(F[m]@w).std();D.append(w/sd);B.append(bb/sd)
    D=np.array(D);B=np.array(B);W2=np.vstack([g*D,-g*D]);b2=np.concatenate([g*B,-g*B])
    if extra:
        k=2  # pair (0,3) index
        for t in [-1.5,-0.75,0.75,1.5]:W2=np.vstack([W2,g*D[k]]);b2=np.append(b2,g*(B[k]+t))
        for i in [8,]:pass
    H=sil(Xt@W1.T)@W2.T+b2;H=sil(H);W3,b3=lda(H,yt,lf);return W1,W2,b2,W3,b3
def run(**kw):
    acc=[]
    for s in range(5):
        p=np.random.default_rng(s).permutation(len(y));tr,te=p[:1000],p[1000:]
        W1,W2,b2,W3,b3=build(X[tr],y[tr],**kw);H=sil(sil(X[te]@W1.T)@W2.T+b2);acc.append(((H@W3.T+b3).argmax(1)==y[te]).mean())
    return round(np.mean(acc),4)
